-- Two things a signed-in player could do through the public API that the app
-- never needs. Run it AFTER the code that reads share pages with the server's
-- key is deployed (lib/server/shared-completions.ts): before that, share pages
-- would stop loading.
--
-- All or nothing: if any statement fails, none of it is applied.
begin;

-- 1. Row ids can't be chosen by the client.
--
-- Both ids could be supplied on insert (games.id was "generated by default",
-- playing_queue.id a bigserial). Row-level security hides other players' rows
-- but the primary key is shared, so someone could insert rows of their own
-- with ids ahead of the sequence, and every other player's import or add that
-- reached one of those ids would fail. The app never sends an id.
alter table games alter column id set generated always;

-- A bigserial is a plain default, which an insert may override: made an
-- identity column that always generates, carrying on from where it was.
do $$
declare
  next_id bigint;
begin
  select greatest(coalesce(max(id), 0), (select last_value from playing_queue_id_seq)) + 1
    into next_id
    from playing_queue;
  alter table playing_queue alter column id drop default;
  drop sequence playing_queue_id_seq;
  execute format(
    'alter table playing_queue alter column id add generated always as identity (start with %s)',
    next_id
  );
end $$;

-- 2. Share pages can't be listed.
--
-- shared_completions was readable by anyone with the public key, which made
-- the unguessable share links a public directory: every page's game, rating,
-- counts and date. The share page and its preview image now read one row, by
-- its id, with the server's key, so nothing else needs to read the table.
drop policy "Shared completions are publicly readable" on shared_completions;
-- Nothing in the app deletes share pages from the browser, and without read
-- access a delete by id couldn't be expressed anyway.
drop policy "Users delete their own shared completions" on shared_completions;
-- Table privileges, and the column grants that went with them.
revoke all on shared_completions from anon, authenticated;

commit;
